[metadata] {"type": "create", "filePath": "/app/output/final_report.html", "content": "<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Global Smartwatch Secondary Market Analysis — Q1 2026</title>
<script src="https://cdn.jsdelivr.net/npm/chart.js@4.4.0/dist/chart.umd.min.js"></script>
<style>
  :root {
    --bg: #0f1117;
    --surface: #1a1d27;
    --surface2: #21263a;
    --border: #2d3350;
    --accent-apple: #3b82f6;
    --accent-garmin: #22c55e;
    --accent-samsung: #f59e0b;
    --text: #e2e8f0;
    --text-muted: #8892a4;
    --positive: #22c55e;
    --negative: #ef4444;
    --neutral: #94a3b8;
    --highlight: #6366f1;
  }
  * { box-sizing: border-box; margin: 0; padding: 0; }
  body {
    font-family: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;
    background: var(--bg);
    color: var(--text);
    line-height: 1.6;
    font-size: 14px;
  }
  .page-header {
    background: linear-gradient(135deg, #1a1d27 0%, #0f1117 60%, #1a1d27 100%);
    border-bottom: 1px solid var(--border);
    padding: 56px 48px 48px;
    position: relative;
    overflow: hidden;
  }
  .page-header::before {
    content: '';
    position: absolute;
    top: -80px; right: -80px;
    width: 400px; height: 400px;
    background: radial-gradient(circle, rgba(99,102,241,0.08) 0%, transparent 70%);
    pointer-events: none;
  }
  .header-badge {
    display: inline-block;
    background: rgba(99,102,241,0.15);
    border: 1px solid rgba(99,102,241,0.3);
    color: #a5b4fc;
    font-size: 11px;
    font-weight: 600;
    letter-spacing: 0.08em;
    text-transform: uppercase;
    padding: 4px 12px;
    border-radius: 20px;
    margin-bottom: 20px;
  }
  .page-header h1 {
    font-size: 32px;
    font-weight: 700;
    letter-spacing: -0.02em;
    color: #f1f5f9;
    margin-bottom: 12px;
    max-width: 640px;
  }
  .page-header p {
    color: var(--text-muted);
    font-size: 15px;
    max-width: 560px;
  }
  .header-meta {
    margin-top: 32px;
    display: flex;
    gap: 32px;
    flex-wrap: wrap;
  }
  .meta-item { display: flex; flex-direction: column; gap: 2px; }
  .meta-label { font-size: 11px; color: var(--text-muted); text-transform: uppercase; letter-spacing: 0.06em; }
  .meta-value { font-size: 14px; font-weight: 600; color: var(--text); }

  .container { max-width: 1200px; margin: 0 auto; padding: 0 32px; }

  .section {
    padding: 48px 0;
    border-bottom: 1px solid var(--border);
  }
  .section:last-child { border-bottom: none; }

  .section-header { margin-bottom: 32px; }
  .section-number {
    font-size: 11px; font-weight: 700; letter-spacing: 0.1em;
    text-transform: uppercase; color: var(--highlight); margin-bottom: 8px;
  }
  .section-title {
    font-size: 22px; font-weight: 700; color: #f1f5f9;
    letter-spacing: -0.02em; margin-bottom: 8px;
  }
  .section-desc { color: var(--text-muted); font-size: 14px; max-width: 680px; }

  /* KPI Cards */
  .kpi-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(180px, 1fr));
    gap: 16px;
    margin-bottom: 40px;
  }
  .kpi-card {
    background: var(--surface);
    border: 1px solid var(--border);
    border-radius: 10px;
    padding: 20px;
    position: relative;
    overflow: hidden;
  }
  .kpi-card::before {
    content: '';
    position: absolute;
    top: 0; left: 0; right: 0;
    height: 3px;
  }
  .kpi-card.blue::before { background: var(--accent-apple); }
  .kpi-card.green::before { background: var(--accent-garmin); }
  .kpi-card.amber::before { background: var(--accent-samsung); }
  .kpi-card.purple::before { background: var(--highlight); }
  .kpi-card.slate::before { background: #64748b; }
  .kpi-label { font-size: 11px; color: var(--text-muted); text-transform: uppercase; letter-spacing: 0.06em; margin-bottom: 8px; }
  .kpi-value { font-size: 28px; font-weight: 700; letter-spacing: -0.03em; color: #f1f5f9; line-height: 1; }
  .kpi-sub { font-size: 12px; color: var(--text-muted); margin-top: 6px; }
  .kpi-delta {
    display: inline-block;
    font-size: 12px; font-weight: 600;
    padding: 2px 8px; border-radius: 4px; margin-top: 8px;
  }
  .kpi-delta.up { background: rgba(34,197,94,0.12); color: #4ade80; }
  .kpi-delta.down { background: rgba(239,68,68,0.12); color: #f87171; }
  .kpi-delta.neutral { background: rgba(148,163,184,0.12); color: #94a3b8; }

  /* Charts */
  .chart-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 24px; margin-top: 24px; }
  .chart-grid.wide { grid-template-columns: 2fr 1fr; }
  .chart-grid.full { grid-template-columns: 1fr; }
  .chart-card {
    background: var(--surface);
    border: 1px solid var(--border);
    border-radius: 10px;
    padding: 24px;
  }
  .chart-title {
    font-size: 13px; font-weight: 600; color: var(--text);
    margin-bottom: 4px;
  }
  .chart-subtitle { font-size: 12px; color: var(--text-muted); margin-bottom: 20px; }
  .chart-container { position: relative; }

  /* Tables */
  .data-table {
    width: 100%;
    border-collapse: collapse;
    font-size: 13px;
    margin-top: 8px;
  }
  .data-table th {
    text-align: left;
    padding: 10px 14px;
    background: var(--surface2);
    color: var(--text-muted);
    font-size: 11px;
    font-weight: 600;
    text-transform: uppercase;
    letter-spacing: 0.05em;
    border-bottom: 1px solid var(--border);
  }
  .data-table td {
    padding: 10px 14px;
    border-bottom: 1px solid rgba(45,51,80,0.5);
    color: var(--text);
  }
  .data-table tr:last-child td { border-bottom: none; }
  .data-table tr:hover td { background: rgba(255,255,255,0.02); }
  .data-table td.num { text-align: right; font-variant-numeric: tabular-nums; font-weight: 500; }
  .badge {
    display: inline-block;
    font-size: 11px; font-weight: 600;
    padding: 2px 8px; border-radius: 4px;
  }
  .badge-apple { background: rgba(59,130,246,0.15); color: #60a5fa; }
  .badge-garmin { background: rgba(34,197,94,0.15); color: #4ade80; }
  .badge-samsung { background: rgba(245,158,11,0.15); color: #fbbf24; }
  .badge-up { background: rgba(34,197,94,0.12); color: #4ade80; }
  .badge-down { background: rgba(239,68,68,0.12); color: #f87171; }
  .badge-neutral { background: rgba(148,163,184,0.12); color: #94a3b8; }

  /* Heatmap */
  .heatmap-wrapper { overflow-x: auto; }
  .heatmap-table {
    width: 100%;
    border-collapse: separate;
    border-spacing: 3px;
    font-size: 12px;
  }
  .heatmap-table th {
    padding: 8px 12px;
    background: transparent;
    color: var(--text-muted);
    font-size: 11px;
    font-weight: 600;
    text-transform: uppercase;
    letter-spacing: 0.05em;
  }
  .heatmap-table th:first-child { text-align: left; }
  .heatmap-table td {
    padding: 10px 14px;
    border-radius: 6px;
    text-align: center;
    font-weight: 600;
    font-size: 12px;
  }
  .heatmap-table td.country-name {
    text-align: left;
    background: var(--surface2);
    color: var(--text);
    border-radius: 6px;
    font-weight: 500;
  }
  .hm-hot4  { background: rgba(239,68,68,0.70); color: #fff; }
  .hm-hot3  { background: rgba(239,68,68,0.45); color: #fecaca; }
  .hm-hot2  { background: rgba(239,68,68,0.22); color: #fca5a5; }
  .hm-hot1  { background: rgba(239,68,68,0.10); color: #f87171; }
  .hm-neutral { background: rgba(148,163,184,0.08); color: var(--text-muted); }
  .hm-cool1 { background: rgba(34,197,94,0.10); color: #4ade80; }
  .hm-cool2 { background: rgba(34,197,94,0.22); color: #22d561; }
  .hm-cool3 { background: rgba(34,197,94,0.45); color: #16a34a; }
  .hm-cool4 { background: rgba(34,197,94,0.70); color: #fff; }
  .hm-na    { background: var(--surface2); color: var(--border); }

  /* Inline stat callouts */
  .callout-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 16px; margin: 24px 0; }
  .callout {
    background: var(--surface);
    border: 1px solid var(--border);
    border-radius: 10px;
    padding: 18px 20px;
  }
  .callout-brand { font-size: 11px; font-weight: 700; text-transform: uppercase; letter-spacing: 0.08em; margin-bottom: 6px; }
  .callout-brand.apple { color: #60a5fa; }
  .callout-brand.garmin { color: #4ade80; }
  .callout-brand.samsung { color: #fbbf24; }
  .callout-stat { font-size: 22px; font-weight: 700; letter-spacing: -0.02em; color: #f1f5f9; margin-bottom: 4px; }
  .callout-desc { font-size: 12px; color: var(--text-muted); }

  /* Legend */
  .legend { display: flex; gap: 20px; flex-wrap: wrap; margin-bottom: 12px; }
  .legend-item { display: flex; align-items: center; gap: 6px; font-size: 12px; color: var(--text-muted); }
  .legend-dot { width: 10px; height: 10px; border-radius: 50%; }

  /* Recommendations */
  .rec-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 20px; }
  .rec-card {
    background: var(--surface);
    border: 1px solid var(--border);
    border-radius: 10px;
    padding: 24px;
    display: flex;
    gap: 16px;
  }
  .rec-icon {
    width: 36px; height: 36px; border-radius: 8px;
    display: flex; align-items: center; justify-content: center;
    font-size: 16px; flex-shrink: 0;
  }
  .rec-icon.sourcing { background: rgba(59,130,246,0.15); }
  .rec-icon.arb      { background: rgba(34,197,94,0.15); }
  .rec-icon.size     { background: rgba(245,158,11,0.15); }
  .rec-icon.seller   { background: rgba(99,102,241,0.15); }
  .rec-body {}
  .rec-tag { font-size: 10px; font-weight: 700; text-transform: uppercase; letter-spacing: 0.08em; color: var(--text-muted); margin-bottom: 6px; }
  .rec-title { font-size: 14px; font-weight: 700; color: #f1f5f9; margin-bottom: 8px; }
  .rec-body p { font-size: 13px; color: var(--text-muted); line-height: 1.6; }
  .rec-body strong { color: var(--text); }

  /* Insight callout boxes */
  .insight-box {
    background: rgba(99,102,241,0.08);
    border: 1px solid rgba(99,102,241,0.2);
    border-radius: 8px;
    padding: 14px 18px;
    margin: 20px 0;
    font-size: 13px;
    color: #c7d2fe;
  }
  .insight-box strong { color: #a5b4fc; }

  .two-col { display: grid; grid-template-columns: 1fr 1fr; gap: 32px; }
  .divider { border: none; border-top: 1px solid var(--border); margin: 32px 0; }

  /* Scale legend for heatmap */
  .scale-bar {
    display: flex; align-items: center; gap: 8px;
    margin-top: 14px; font-size: 11px; color: var(--text-muted);
  }
  .scale-gradient {
    flex: 1; height: 8px; border-radius: 4px;
    background: linear-gradient(to right, rgba(34,197,94,0.7), rgba(148,163,184,0.08), rgba(239,68,68,0.7));
  }

  @media (max-width: 768px) {
    .chart-grid { grid-template-columns: 1fr; }
    .chart-grid.wide { grid-template-columns: 1fr; }
    .callout-grid { grid-template-columns: 1fr; }
    .rec-grid { grid-template-columns: 1fr; }
    .two-col { grid-template-columns: 1fr; }
    .page-header { padding: 32px 24px; }
    .container { padding: 0 20px; }
    .kpi-grid { grid-template-columns: repeat(2, 1fr); }
  }
</style>
</head>
<body>

<!-- ===== PAGE HEADER ===== -->
<div class="page-header">
  <div class="container">
    <div class="header-badge">Market Intelligence Report</div>
    <h1>Global Smartwatch Secondary Market Analysis</h1>
    <p>Pricing dynamics, geographic arbitrage, and seller behavior patterns across 3,607 active resale listings — Apple, Garmin, and Samsung — Q1 2026.</p>
    <div class="header-meta">
      <div class="meta-item"><span class="meta-label">Dataset</span><span class="meta-value">3,607 listings</span></div>
      <div class="meta-item"><span class="meta-label">Brands</span><span class="meta-value">Apple · Garmin · Samsung</span></div>
      <div class="meta-item"><span class="meta-label">Markets</span><span class="meta-value">27 countries</span></div>
      <div class="meta-item"><span class="meta-label">Sellers</span><span class="meta-value">1,754 unique</span></div>
      <div class="meta-item"><span class="meta-label">Period</span><span class="meta-value">Q1 2026</span></div>
    </div>
  </div>
</div>

<div class="container">

<!-- ===== SECTION 1: MARKET OVERVIEW ===== -->
<div class="section">
  <div class="section-header">
    <div class="section-number">01 — Market Overview</div>
    <div class="section-title">Market Overview &amp; Listing Composition</div>
    <div class="section-desc">Snapshot of the secondary smartwatch marketplace: brand distribution, condition mix, geographic spread, and baseline pricing.</div>
  </div>

  <div class="kpi-grid">
    <div class="kpi-card blue">
      <div class="kpi-label">Total Listings</div>
      <div class="kpi-value">3,607</div>
      <div class="kpi-sub">Apple · Garmin · Samsung + other</div>
    </div>
    <div class="kpi-card blue">
      <div class="kpi-label">Overall Median Price</div>
      <div class="kpi-value">$550</div>
      <div class="kpi-sub">Across all 3 main brands</div>
    </div>
    <div class="kpi-card green">
      <div class="kpi-label">Countries</div>
      <div class="kpi-value">27</div>
      <div class="kpi-sub">Active seller markets</div>
    </div>
    <div class="kpi-card amber">
      <div class="kpi-label">Unique Sellers</div>
      <div class="kpi-value">1,754</div>
      <div class="kpi-sub">Anonymized IDs</div>
    </div>
    <div class="kpi-card purple">
      <div class="kpi-label">Worldwide Shipping</div>
      <div class="kpi-value">27%</div>
      <div class="kpi-sub">Of all listings</div>
    </div>
  </div>

  <div class="chart-grid">
    <div class="chart-card">
      <div class="chart-title">Brand Share of Listings</div>
      <div class="chart-subtitle">Apple dominates with 66% of all active listings</div>
      <div class="chart-container" style="height:260px">
        <canvas id="brandShareChart"></canvas>
      </div>
    </div>
    <div class="chart-card">
      <div class="chart-title">Condition Mix — All Brands</div>
      <div class="chart-subtitle">53% of listings are new or open box</div>
      <div class="chart-container" style="height:260px">
        <canvas id="conditionChart"></canvas>
      </div>
    </div>
  </div>

  <div class="chart-grid" style="margin-top:24px">
    <div class="chart-card">
      <div class="chart-title">Top Markets by Listing Volume</div>
      <div class="chart-subtitle">United States accounts for 65% of all listings</div>
      <div class="chart-container" style="height:280px">
        <canvas id="countryVolumeChart"></canvas>
      </div>
    </div>
    <div class="chart-card">
      <div class="chart-title">Brand Mix by Country (top 6)</div>
      <div class="chart-subtitle">Samsung concentration is highest in South Korea &amp; UK</div>
      <div class="chart-container" style="height:280px">
        <canvas id="countryBrandStackChart"></canvas>
      </div>
    </div>
  </div>
</div>

<!-- ===== SECTION 2: BRAND PRICING ===== -->
<div class="section">
  <div class="section-header">
    <div class="section-number">02 — Brand Pricing</div>
    <div class="section-title">Brand-Level Pricing &amp; Value Retention</div>
    <div class="section-desc">Median, mean, and spread of resale prices across Apple, Garmin, and Samsung. Identifies which brand commands the strongest value retention and which shows the widest variance.</div>
  </div>

