// Price Distribution (simulated box-plot using bar segments)
// We'll show min/q1/median/q3/max as floating bars
// Apple: q1~350, median~550, q3~699, mean~595, min~120, max~40500 (capped)
// Garmin: q1~484, median~567, q3~699, min~215, max~1319
// Samsung: q1~330, median~530, q3~699, min~245, max~49900 (capped)
new Chart(document.getElementById('priceDistChart'), {
  type: 'bar',
  data: {
    labels: ['Apple', 'Garmin', 'Samsung'],
    datasets: [
      {
        label: 'Q1–Q3 Range',
        data: [
          [350, 699],
          [484, 699],
          [330, 699]
        ],
        backgroundColor: ['rgba(59,130,246,0.35)','rgba(34,197,94,0.35)','rgba(245,158,11,0.35)'],
        borderColor: ['#3b82f6','#22c55e','#f59e0b'],
        borderWidth: 1,
        borderSkipped: false,
        borderRadius: 4,
        barPercentage: 0.5
      }
    ]
  },
  options: {
    responsive: true, maintainAspectRatio: false,
    plugins: {
      legend: { display: false },
      tooltip: {
        callbacks: {
          label: (ctx) => {
            const ranges = { Apple: 'Q1: $350 · Median: $550 · Q3: $699', Garmin: 'Q1: $484 · Median: $567 · Q3: $699', Samsung: 'Q1: $330 · Median: $530 · Q3: $699' };
            return ranges[ctx.label] || '';
          }
        }
      },
      annotation: { }
    },
    scales: {
      x: { grid: { display: false }, ticks: { color: '#c4ccd8', font: { size: 13, weight: '600' } } },
      y: { grid: { color: '#1e2235' }, ticks: { color: '#8892a4', callback: v => '$'+v } }
    }
  },
  plugins: [{
    id: 'medianLines',
    afterDatasetsDraw(chart) {
      const { ctx, chartArea, scales } = chart;
      const medians = [550, 567, 530];
      const colors = ['#3b82f6', '#22c55e', '#f59e0b'];
      const meta = chart.getDatasetMeta(0);
      medians.forEach((med, i) => {
        const bar = meta.data[i];
        if (!bar) return;
        const y = scales.y.getPixelForValue(med);
        const x1 = bar.x - bar.width/2 - 8;
        const x2 = bar.x + bar.width/2 + 8;
        ctx.save();
        ctx.strokeStyle = colors[i];
        ctx.lineWidth = 2.5;
        ctx.beginPath(); ctx.moveTo(x1, y); ctx.lineTo(x2, y); ctx.stroke();
        ctx.fillStyle = colors[i];
        ctx.font = 'bold 11px Inter, sans-serif';
        ctx.fillText('median $' + med, x2 + 6, y + 4);
        ctx.restore();
      });
    }
  }]
});

