// Build heatmap
const allCountries = [...new Set([
  ...Object.keys(geoData.Apple),
  ...Object.keys(geoData.Garmin),
  ...Object.keys(geoData.Samsung)
])].sort();

function heatClass(pct) {
  if (pct === null) return 'hm-na';
  if (pct > 40) return 'hm-hot4';
  if (pct > 20) return 'hm-hot3';
  if (pct > 8)  return 'hm-hot2';
  if (pct > 0)  return 'hm-hot1';
  if (pct > -5) return 'hm-neutral';
  if (pct > -12) return 'hm-cool1';
  if (pct > -22) return 'hm-cool2';
  if (pct > -30) return 'hm-cool3';
  return 'hm-cool4';
}

const tbody = document.getElementById('heatmapBody');
allCountries.forEach(country => {
  const a = geoData.Apple[country];
  const g = geoData.Garmin[country];
  const s = geoData.Samsung[country];
  const tr = document.createElement('tr');
  const fmt = v => v ? `${v.pct >= 0 ? '+' : ''}${v.pct.toFixed(1)}%<br><small style="font-weight:400;opacity:0.8">$${v.median.toFixed(0)}</small>` : '—';
  tr.innerHTML = `
    <td class="country-name">${country}</td>
    <td class="${heatClass(a ? a.pct : null)}">${fmt(a)}</td>
    <td class="${heatClass(g ? g.pct : null)}">${fmt(g)}</td>
    <td class="${heatClass(s ? s.pct : null)}">${fmt(s)}</td>
  `;
  tbody.appendChild(tr);
});

// Apple Geo Chart
function makeDivergingChart(canvasId, data, globalMedian, color) {
  const sorted = Object.entries(data).sort((a, b) => b[1].pct - a[1].pct);
  const labels = sorted.map(x => x[0]);
  const vals = sorted.map(x => x[1].pct);
  const colors = vals.map(v => v >= 0 ? color + 'cc' : 'rgba(34,197,94,0.7)');
  const borderColors = vals.map(v => v >= 0 ? color : '#22c55e');

  new Chart(document.getElementById(canvasId), {
    type: 'bar',
    data: {
      labels,
      datasets: [{
        label: '% vs global median',
        data: vals,
        backgroundColor: colors,
        borderColor: borderColors,
        borderWidth: 1,
        borderRadius: 3,
        borderSkipped: false
      }]
    },
    options: {
      indexAxis: 'y',
      responsive: true, maintainAspectRatio: false,
      plugins: {
        legend: { display: false },
        tooltip: {
          callbacks: {
            label: ctx => {
              const c = sorted[ctx.dataIndex][0];
              const v = geoData[canvasId.includes('apple') ? 'Apple' : canvasId.includes('garmin') ? 'Garmin' : 'Samsung'][c];
              return ` ${v.pct >= 0 ? '+' : ''}${v.pct.toFixed(1)}% ($${v.median.toFixed(0)} vs global $${globalMedian})`;
            }
          }
        }
      },
      scales: {
        x: {
          grid: { color: '#1e2235' },
          ticks: { color: '#8892a4', callback: v => v + '%' }
        },
        y: { grid: { display: false }, ticks: { color: '#c4ccd8' } }
      }
    }
  });
}

